import { useState } from "react";
import { Mail, Lock, Eye, EyeOff, ArrowRight } from 'lucide-react';
import StudentDashboard from "../StudentDashboard";
import MentorDashboard from "../MentorDashboard";
import PlacementDashboard from "../PlacementDashboard";

const ProfessionalLogin = () => {
  const [selectedUserType, setSelectedUserType] = useState('');
  const [showLogin, setShowLogin] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [loginData, setLoginData] = useState({ email: '', password: '' });
  const [loginError, setLoginError] = useState('');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [authenticatedUser, setAuthenticatedUser] = useState(null);

  const VALID_CREDENTIALS = {
    'student': { email: 'student@college.edu', password: 'student123' },
    'mentor': { email: 'mentor@college.edu', password: 'mentor123' },
    'placement-cell': { email: 'placement@college.edu', password: 'placement123' }
  };

  const userTypes = [
    { id: 'student', title: 'Student', description: 'Access your placement dashboard' },
    { id: 'mentor', title: 'Mentor', description: 'Guide and review student applications' },
    { id: 'placement-cell', title: 'Placement Cell', description: 'Manage campus recruitment' }
  ];

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoginError('');
    setIsLoading(true);

    const creds = VALID_CREDENTIALS[selectedUserType];

    setTimeout(() => {
      if (loginData.email === creds.email && loginData.password === creds.password) {
        setIsAuthenticated(true);
        setAuthenticatedUser({
          email: loginData.email,
          userType: selectedUserType,
          name: selectedUserType.charAt(0).toUpperCase() + selectedUserType.slice(1)
        });
      } else {
        setLoginError('Invalid email or password');
      }
      setIsLoading(false);
    }, 600);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setAuthenticatedUser(null);
    setSelectedUserType('');
    setShowLogin(false);
    setLoginData({ email: '', password: '' });
    setLoginError('');
  };

  if (isAuthenticated && authenticatedUser) {
    if (authenticatedUser.userType === 'student') {
      return <StudentDashboard onLogout={handleLogout} />;
    } else if (authenticatedUser.userType === 'mentor') {
      return <MentorDashboard onLogout={handleLogout} />;
    } else if (authenticatedUser.userType === 'placement-cell') {
      return <PlacementDashboard onLogout={handleLogout} />;
    }
  }

  if (showLogin && selectedUserType) {
    const currentUserType = userTypes.find(ut => ut.id === selectedUserType);
    const credentials = VALID_CREDENTIALS[selectedUserType];

    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
        <div className="w-full max-w-md">
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-8">
            <button
              onClick={() => {
                setShowLogin(false);
                setSelectedUserType('');
                setLoginData({ email: '', password: '' });
                setLoginError('');
              }}
              className="mb-6 text-sm text-gray-600 hover:text-gray-900 transition-colors"
            >
              ← Back
            </button>

            <div className="mb-8">
              <h1 className="text-2xl font-semibold text-gray-900 mb-1">
                Sign in to CampusConnect
              </h1>
              <p className="text-sm text-gray-600">
                {currentUserType.title} Portal
              </p>
            </div>

            <form onSubmit={handleLogin} className="space-y-5">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">
                  Email
                </label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-gray-400" />
                  <input
                    type="email"
                    required
                    value={loginData.email}
                    onChange={(e) => setLoginData({ ...loginData, email: e.target.value })}
                    className="w-full pl-10 pr-4 py-2.5 border border-gray-300 rounded-lg text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition-colors"
                    placeholder="you@college.edu"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">
                  Password
                </label>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-gray-400" />
                  <input
                    type={showPassword ? "text" : "password"}
                    required
                    value={loginData.password}
                    onChange={(e) => setLoginData({ ...loginData, password: e.target.value })}
                    className="w-full pl-10 pr-12 py-2.5 border border-gray-300 rounded-lg text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition-colors"
                    placeholder="Enter password"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
                  >
                    {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                  </button>
                </div>
              </div>

              {loginError && (
                <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
                  <p className="text-sm text-red-700">{loginError}</p>
                </div>
              )}

              <div className="p-3 bg-blue-50 border border-blue-100 rounded-lg">
                <p className="text-xs font-medium text-gray-700 mb-1">Demo Credentials</p>
                <p className="text-xs text-gray-600">{credentials.email} / {credentials.password}</p>
              </div>

              <button
                type="submit"
                disabled={isLoading}
                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-medium py-2.5 rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-2"
              >
                {isLoading ? (
                  <>
                    <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                    <span>Signing in...</span>
                  </>
                ) : (
                  <>
                    <span>Sign in</span>
                    <ArrowRight className="h-4 w-4" />
                  </>
                )}
              </button>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white">
      {/* Simple Header */}
      <header className="border-b border-gray-200">
        <div className="max-w-6xl mx-auto px-6 py-4">
          <h1 className="text-lg font-semibold text-gray-900">CampusConnect</h1>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-4xl mx-auto px-6 py-16">
        {/* Title */}
        <div className="text-center mb-16">
          <h2 className="text-4xl font-bold text-gray-900 mb-4">
            Campus Placement Management
          </h2>
          <p className="text-lg text-gray-600">
            Streamline your placement process with our comprehensive platform
          </p>
        </div>

        {/* User Type Cards */}
        <div className="grid md:grid-cols-3 gap-6 mb-12">
          {userTypes.map((userType) => (
            <button
              key={userType.id}
              onClick={() => {
                setSelectedUserType(userType.id);
                setShowLogin(true);
              }}
              className="bg-white border border-gray-200 rounded-lg p-6 text-left hover:border-gray-300 hover:shadow-sm transition-all"
            >
              <h3 className="text-lg font-semibold text-gray-900 mb-2">
                {userType.title}
              </h3>
              <p className="text-sm text-gray-600 mb-4">
                {userType.description}
              </p>
              <div className="flex items-center text-blue-600 text-sm font-medium">
                <span>Access portal</span>
                <ArrowRight className="h-4 w-4 ml-1" />
              </div>
            </button>
          ))}
        </div>

        {/* Simple Features */}
        <div className="grid md:grid-cols-3 gap-8 pt-12 border-t border-gray-200">
          <div>
            <h4 className="font-semibold text-gray-900 mb-2">Track Applications</h4>
            <p className="text-sm text-gray-600">Monitor your placement applications in real-time</p>
          </div>
          <div>
            <h4 className="font-semibold text-gray-900 mb-2">Connect with Mentors</h4>
            <p className="text-sm text-gray-600">Get guidance from experienced professionals</p>
          </div>
          <div>
            <h4 className="font-semibold text-gray-900 mb-2">Manage Recruitment</h4>
            <p className="text-sm text-gray-600">Coordinate campus drives efficiently</p>
          </div>
        </div>
      </main>

      {/* Footer */}
      <footer className="border-t border-gray-200 mt-20">
        <div className="max-w-6xl mx-auto px-6 py-8">
          <div className="flex flex-col md:flex-row items-center justify-between text-sm text-gray-600">
            <p>© 2025 CampusConnect. All rights reserved.</p>
            <div className="flex space-x-6 mt-4 md:mt-0">
              <span className="hover:text-gray-900 cursor-pointer">Privacy</span>
              <span className="hover:text-gray-900 cursor-pointer">Terms</span>
              <span className="hover:text-gray-900 cursor-pointer">Contact</span>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default ProfessionalLogin;
